
.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.tag,
.empty {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: 999px;
  border: 1px solid rgba(53, 94, 92, 0.2);
  background: rgba(255, 255, 255, 0.56);
  color: var(--ink-muted);
  font-size: 12px;
}

.tag strong {
  color: var(--ink-text);
  font-weight: 600;
}

.empty {
  border-style: dashed;
}
